def render_cocktail_input() -> tuple[str, str, bool]:
    """
    Render hybrid questionnaire: text input + budget dropdown + surprise button.

    Returns:
        tuple: (query, budget, is_surprise)
    """
    st.markdown("""
        <p style="text-align: center; font-size: 1.1rem; color: #A9B8D6; margin-bottom: 1rem; font-family: Poppins, Arial, sans-serif;">
            <em>Décrivez votre envie, le barman s'occupe du reste...</em>
        </p>
    """, unsafe_allow_html=True)

    col1, col2, col3 = st.columns([1, 4, 1])

    with col2:
        query = st.text_input(
            label="Votre commande",
            placeholder="Un cocktail fruite et rafraichissant...",
            label_visibility="collapsed",
            key="cocktail_query"
        )

        st.markdown("""
            <p style="font-size: 0.875rem; color: #A9B8D6; margin: 0.8rem 0 0.3rem 0;">
                <em>Votre budget pour ce soir ?</em>
            </p>
        """, unsafe_allow_html=True)

        budget = st.selectbox(
            label="Budget",
            options=[
                "Economique (< 8€)",
                "Modere (8-15€)",
                "Premium (15-25€)",
                "Luxe (> 25€)"
            ],
            index=1,
            label_visibility="collapsed",
            key="budget_select"
        )

        # Buttons row
        btn_col1, btn_col2 = st.columns(2)

        with btn_col1:
            submitted = st.button(
                "Invoquer le Barman",
                use_container_width=True,
                type="primary"
            )

        with btn_col2:
            surprise = st.button(
                "Surprends-moi !",
                use_container_width=True,
            )

    if surprise:
        return random.choice(SURPRISE_QUERIES), budget, True
    elif submitted and query:
        return query, budget, False
    return "", "", False


